import { useEffect, useId, useRef, useState } from 'react';
import { setColorOpacity, useColorOpacity } from './colorOpacity';
import { setTheme, themeDefinitions, useTheme } from './theme';
import './themeToggle.css';

export function ThemeToggle() {
  const theme = useTheme(), next = theme === 'dark' ? 'light' : 'dark';
  const opacity = useColorOpacity(), [open, setOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null), opener = useRef<HTMLButtonElement>(null), panelId = useId();
  useEffect(() => {
    if (!open) return;
    const outside = (event: PointerEvent) => { if (!ref.current?.contains(event.target as Node)) setOpen(false); };
    window.addEventListener('pointerdown', outside, true);
    return () => window.removeEventListener('pointerdown', outside, true);
  }, [open]);
  return <div className="theme-picker" ref={ref} onKeyDown={event => {
    if (event.key === 'Escape' && open) { event.stopPropagation(); setOpen(false); opener.current?.focus(); }
  }}>
    {open && <section className="theme-picker-panel" id={panelId} aria-label="Appearance settings">
      <strong>Treemap colors</strong>
      <label><span>Color scale</span>
        <select aria-label="Treemap color scale" value={opacity.scale}
          onChange={event => setColorOpacity('scale', event.target.value === 'continuous' ? 'continuous' : 'ranked')}>
          <option value="ranked">Ranked</option><option value="continuous">Continuous</option>
        </select>
        <small>{opacity.scale === 'ranked' ? 'Evenly spaced shades by LOC rank. Equal LOC shares a shade.' : 'Shade changes proportionally with LOC.'}</small>
      </label>
      {(['treemap', 'canvas'] as const).map(key => <label key={key}>
        <span>{key === 'treemap' ? 'Diagram treemap' : 'Diagram backgrounds'}<output>{opacity[key]}%</output></span>
        <input type="range" min="0" max="100" step="1" value={opacity[key]}
          aria-label={key === 'treemap' ? 'Treemap color opacity' : 'Diagram background opacity'}
          aria-valuetext={`${opacity[key]}% opaque`} onChange={event => setColorOpacity(key, Number(event.target.value))} />
      </label>)}
      <small>0% transparent · 100% solid</small>
      <label><span>Shade shift<output>{opacity.shade > 0 ? '+' : ''}{opacity.shade}</output></span>
        <input type="range" min="-20" max="20" step="1" value={opacity.shade} aria-label="Shade shift"
          aria-valuetext={opacity.shade === 0 ? 'Default shade' : `${Math.abs(opacity.shade)} ${opacity.shade > 0 ? 'lighter' : 'darker'}`}
          onChange={event => setColorOpacity('shade', Number(event.target.value))} />
        <small>Darker ← · → Lighter</small>
      </label>
    </section>}
    <div className="theme-picker-buttons"><button className="theme-toggle" type="button" onClick={() => setTheme(next)}
    aria-label={`Switch to ${themeDefinitions[next].label}`} title={`Current theme: ${themeDefinitions[theme].label}`}>
    <svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true" fill="none" stroke="currentColor" strokeWidth="1.5">
      {theme === 'dark' ? <><circle cx="12" cy="12" r="4" /><path d="M12 1v3m0 16v3M1 12h3m16 0h3M4.2 4.2l2.1 2.1m11.4 11.4 2.1 2.1M4.2 19.8l2.1-2.1M17.7 6.3l2.1-2.1" /></>
        : <path d="M20.5 14.1A9 9 0 0 1 9.9 3.5 9 9 0 1 0 20.5 14.1Z" />}
    </svg>
    <span>{theme === 'dark' ? 'Light theme' : 'Dark theme'}</span>
    </button><button ref={opener} type="button" className="theme-settings-toggle" aria-label="Color opacity settings"
      aria-expanded={open} aria-controls={panelId} onClick={() => setOpen(value => !value)} title="Color opacity settings">
      <svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true" fill="none" stroke="currentColor" strokeWidth="1.5">
        <path d="M4 7h7m4 0h5M4 17h3m4 0h9" /><circle cx="13" cy="7" r="2" /><circle cx="9" cy="17" r="2" />
      </svg>
    </button></div>
  </div>;
}

sources.src/shared/theme/colorOpacity.ts:
import { useSyncExternalStore } from 'react';

export const colorOpacityStorageKey = 'new-diagram-color-opacity';
export type TreemapColorScale = 'ranked' | 'continuous';
export type ColorOpacity = { treemap: number; canvas: number; shade: number; scale: TreemapColorScale };
const defaults: ColorOpacity = { treemap: 22, canvas: 22, shade: 0, scale: 'ranked' };
let current = defaults;
const listeners = new Set<() => void>();
const normalize = (value: unknown) => typeof value === 'number' && Number.isFinite(value)
  ? Math.round(Math.max(0, Math.min(100, value))) : 22;

function apply(value: Partial<ColorOpacity> | null) {
  current = { treemap: normalize(value?.treemap), canvas: normalize(value?.canvas),
    scale: value?.scale === 'continuous' ? 'continuous' : 'ranked',
    shade: typeof value?.shade === 'number' && Number.isFinite(value.shade) ? Math.round(Math.max(-20, Math.min(20, value.shade))) : 0 };
  for (const key of ['treemap', 'canvas'] as const)
    document.documentElement.style.setProperty(`--${key}-identity-opacity`, `${current[key]}%`);
  document.documentElement.style.setProperty('--treemap-shade-shift', `${current.shade}%`);
  [...listeners].forEach(listener => listener());
}

export function initializeColorOpacity() {
  const restore = () => {
    try { apply(JSON.parse(localStorage.getItem(colorOpacityStorageKey) ?? 'null')); }
    catch { apply(defaults); }
  };
  restore();
  const synchronize = (event: StorageEvent) => {
    if (event.key === colorOpacityStorageKey || event.key === null) restore();
  };
  window.addEventListener('storage', synchronize);
  return () => window.removeEventListener('storage', synchronize);
}

export function setColorOpacity<K extends keyof ColorOpacity>(key: K, value: ColorOpacity[K]) {
  apply({ ...current, [key]: value });
  try { localStorage.setItem(colorOpacityStorageKey, JSON.stringify(current)); }
  catch { /* Controls still work when browser storage is unavailable. */ }
}

const subscribe = (listener: () => void) => { listeners.add(listener); return () => { listeners.delete(listener); }; };
export const useColorOpacity = () => useSyncExternalStore(subscribe, () => current, () => defaults);

